import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Signal 双棘轮","description":"","frontmatter":{"title":"Signal 双棘轮","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/double-ratchet.md","filePath":"cs/double-ratchet.md","lastUpdated":1789023840000}'),p={name:"cs/double-ratchet.md"};function E(u,a,D,_,m,A){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="signal-双棘轮" tabindex="-1">Signal 双棘轮 <a class="header-anchor" href="#signal-双棘轮" aria-label="Permalink to &quot;Signal 双棘轮&quot;">​</a></h1><div class="epigraph"><p>DH 棘轮换根，对称棘轮用 KDF 推下一条链密钥：每条消息一把键，过去的键删掉。前向保密变成消息粒度，延迟乱序用跳过的键缓存来收。</p><footer>—— Perrin and Marlinspike, The Double Ratchet Algorithm；对照 Krawczyk 的 KDF 提取</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/forward-secrecy">前向保密</a>停在「每个会话一把临时 DH」。缺口是<strong>长时间对话</strong>：消息很多、可乱序、可延迟。双棘轮把 PFS 推到消息级，并引入后向保密（泄漏后未来仍能自愈）的工程直觉。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TLS 会话相对短。即时通讯里同一对端持续数年。每条消息都做完整握手太贵。双棘轮：收到新 DH 公钥就进一格 DH 棘轮；同格内用 HKDF 推链。缺口是状态机，不是再定义 ECDH。</p><h3 id="不是区块链" tabindex="-1">不是区块链 <a class="header-anchor" href="#不是区块链" aria-label="Permalink to &quot;不是区块链&quot;">​</a></h3><p>棘轮是密钥演化，不需要全局账本。不要把本课写成加密货币。</p><p><span class="marginnote">Signal 协议规格公开。本课不写客户端取证步骤。跳过的消息键要限时缓存，否则乱序无法解密。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 DH 棘轮与对称棘轮两条轴。指出会话建立仍要身份（X3DH 只点名）。丢失消息：保留若干跳过键。对照 TLS：记录层序号 vs 消息链。</p>',12)),(e(),s(c,null,{default:r(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DH%5B%22DH%20%E6%A3%98%E8%BD%AE%E6%8D%A2%E6%A0%B9%22%5D%20--%3E%20CK%5B%22%E9%93%BE%E5%AF%86%E9%92%A5%22%5D%0A%20%20CK%20--%3E%20MK%5B%22%E6%B6%88%E6%81%AF%E9%94%AE%22%5D%0A%20%20MK%20--%3E%20DEL%5B%22%E7%94%A8%E5%90%8E%E5%88%A0%E9%99%A4%22%5D%0A%20%20CK%20--%3E%20CK2%5B%22HKDF%20%E6%8E%A8%E4%B8%8B%E4%B8%80%E9%93%BE%E9%94%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>消息键短命，服务前向：旧密文在键删后不可解。新 DH 进格服务后向：当前链泄漏后，下一格根与之独立。身份仍依赖长期身份钥与预密钥包——那是PKI/信任启动，不是棘轮算术。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 X3DH 的全部代数写完。后量子下一课：KEM 替换 DH 格时，棘轮形状仍在，困难问题换成格上封装。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>会话级 PFS 不够长对话；棘轮到消息键。</li><li>DH 换根 + HKDF 链；用后删键。</li><li>乱序靠有限跳过缓存，不是无限保留。</li><li>下一课：后量子 Kyber/Dilithium 换困难问题。</li><li>出处：Perrin and Marlinspike, Double Ratchet；RFC 5869；对照 TLS 1.3。</li></ul>',8))])}const S=l(p,[["render",E]]);export{f as __pageData,S as default};
